<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
$adminId=max(0,scalar_int($_GET['admin_id']??0));$event=trim(scalar_string($_GET['event']??''));$page=max(1,scalar_int($_GET['page']??1,1));$where=[];$params=[];if($adminId>0){$where[]='l.admin_id=?';$params[]=$adminId;}if($event!==''){$where[]='l.event_key LIKE ?';$params[]='%'.str_replace(['%','_'],['\\%','\\_'],$event).'%';}$sql='SELECT l.*,a.full_name FROM admin_activity_logs l LEFT JOIN admins a ON a.id=l.admin_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY l.id DESC LIMIT 100 OFFSET '.(($page-1)*100);$stmt=db()->prepare($sql);$stmt->execute($params);$logs=$stmt->fetchAll();$admins=db()->query('SELECT id,full_name FROM admins ORDER BY full_name')->fetchAll();$adminPage='audit';$adminTitle='گزارش فعالیت مدیران';require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><div><h1>گزارش فعالیت مدیران</h1><p class="muted">ورود، خروج، تغییرات پنل و تلاش‌های غیرمجاز ثبت می‌شوند.</p></div></div><form class="card inline-form" method="get"><select name="admin_id"><option value="0">همه مدیران</option><?php foreach($admins as $admin):?><option value="<?=$admin['id']?>" <?=$adminId==(int)$admin['id']?'selected':''?>><?=e($admin['full_name'])?></option><?php endforeach?></select><input name="event" value="<?=e($event)?>" placeholder="نوع رویداد"><button class="btn btn-secondary">فیلتر</button></form><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>زمان</th><th>مدیر</th><th>رویداد</th><th>مسیر</th><th>IP</th><th>جزئیات</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e(jalali_format($log['created_at']))?></td><td><?=e($log['full_name']?:$log['username']?:'ناشناس')?></td><td dir="ltr"><?=e($log['event_key'])?></td><td><small dir="ltr"><?=e($log['request_method'].' '.$log['route'])?></small></td><td dir="ltr"><?=e($log['ip_address']?:'—')?></td><td><small><?=e(text_substr((string)$log['details_json'],0,180)?:'—')?></small></td></tr><?php endforeach?><?php if(!$logs):?><tr><td colspan="6">گزارشی پیدا نشد.</td></tr><?php endif?></tbody></table></div><?php if(count($logs)===100):?><a class="btn btn-secondary" href="<?=e(app_url('admin/activity-logs.php?page='.($page+1).'&admin_id='.$adminId.'&event='.rawurlencode($event)))?>">صفحه بعد</a><?php endif?>
<?php require __DIR__.'/partials/footer.php';
